      name: 'Amara Okafor',
      role: 'Frontend Engineer, Northwind',
      initials: 'AO',
      color: 'bg-blue-500'
    },
    {
      quote: 'The CSS output stays tiny even as our component library grows. Exactly the balance we were looking for.',
      name: 'Diego Ramirez',
      role: 'Product Designer, Lumen',
      initials: 'DR',
      color: 'bg-emerald-500'
    },
    {
      quote: 'No build step and fantastic DX. It works the same in our SSR pages and our client apps.',
      name: 'Priya Nair',
      role: 'Full-stack Developer, Kite',
      initials: 'PN',
      color: 'bg-purple-500'
    }
  ];

  const section = document.createElement('section');
  section.id = 'testimonials';
  section.className = 'max-w-6xl mx-auto px-6 py-16 sm:py-20';

  const cards = testimonials.map(t => `
    <figure class="flex flex-col h-full bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-2xl shadow-sm p-8 transition duration-300 hover:shadow-xl hover:-translate-y-1">
      <blockquote class="flex-1 text-lg leading-relaxed text-gray-700 dark:text-gray-200">
        &ldquo;${t.quote}&rdquo;
      </blockquote>
      <figcaption class="flex items-center gap-4 mt-6 pt-6 border-t border-gray-100 dark:border-gray-700">
        <div class="flex items-center justify-center w-12 h-12 rounded-full ${t.color} text-white font-semibold text-sm shrink-0">${t.initials}</div>
        <div>
          <div class="font-semibold text-gray-900 dark:text-white">${t.name}</div>
          <div class="text-sm text-gray-500 dark:text-gray-400">${t.role}</div>
        </div>
      </figcaption>
    </figure>
  `).join('');

  section.innerHTML = `
    <div class="max-w-2xl mx-auto text-center mb-12">
      <span class="inline-block text-sm font-medium uppercase tracking-wide text-blue-600 dark:text-blue-400 mb-3">Testimonials</span>
      <h2 class="text-3xl sm:text-4xl font-bold text-gray-900 dark:text-white">Loved by developers and designers</h2>
      <p class="mt-4 text-lg text-gray-600 dark:text-gray-300">Teams rely on BaroCSS for instant styling without the build overhead.</p>
    </div>
    <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
      ${cards}
    </div>
  `;

  hero.insertAdjacentElement('afterend', section);
  return { inserted: true, id: section.id };
}

