() => {
  const rules = [];
  for (const sheet of document.styleSheets) {
    let r;
    try { r = sheet.cssRules; } catch(e){ continue; }
    for (const rule of r) {
      const t = rule.cssText || '';
      if (/\bborder(?![-\w])/.test(rule.selectorText||'') || /border-width|\.border\b|\.border-2\b|\.border-t\b/.test(t)) {
        if (t.length < 200) rules.push(t);
      }
    }
  }
  // find an existing element on the page using border classes (not ours)
  const existing = [...document.querySelectorAll('[class*="border"]')].filter(el=>!el.closest('#testimonials'))[0];
  let existInfo = null;
  if (existing) {
    existInfo = { cls: existing.className, w: getComputedStyle(existing).borderTopWidth };
  }
  return { sampleRules: rules.slice(0,15), existInfo };
}

() => {
  const header = document.querySelector('header');
  const hcs = getComputedStyle(header);
  // check cascade: gather all matching rules for .border via specificity by testing a fresh element in a tick
  const probe = document.createElement('div');
  probe.className = 'border';
  document.body.appendChild(probe);
  const before = getComputedStyle(probe).borderTopWidth;
  // check if there's a reset rule setting border-width:0
  let resets = [];
  for (const sheet of document.styleSheets) {
    let r; try { r = sheet.cssRules; } catch(e){ continue; }
    for (const rule of r) {
      const t = rule.cssText||'';
      if (/border-width:\s*0/.test(t) && t.length<300) resets.push(t);
    }
  }
  probe.remove();
  return {
    headerBorderBottom: hcs.borderBottomWidth + ' ' + hcs.borderBottomStyle,
    probeBorderTop: before,
    resets: resets.slice(0,10)
  };
}

